    for(k2=0;k2<n;k2++){c=ORD[k2];if(!C.act[c.i])continue;dt=t-c.T;if(dt<1.4)crumbs(g,C,S,c,dt);}
    var fd=1-sm(seg(t,[11.2,T.clean]));for(k2=0;k2<n;k2++){c=ORD[k2];if(!C.act[c.i])continue;dt=t-c.T;if(dt<2.4)dust(g,C,S,c,dt,fd);}
