  var xs=-3.5,xe=tail[0]+3.6,n=Math.max(2,Math.round((xs-xe)/5.4));
  for(i=1;i<n;i++){var u=i/n;P.push([xs+(xe-xs)*u,lerp(10.4,tail[1]-3.4,u)+(i%2?-1.2:1.1)*(1-.5*u)]);}
