  var iT=P.length;for(i=sp.length-1;i>=0;i--)P.push(sp[i]);            // the painted spine, tail -> head front
  var R=catmull(P,24),X=R[0],Y=R[1],cum=[0];for(i=1;i<X.length;i++)cum.push(cum[i-1]+Math.hypot(X[i]-X[i-1],Y[i]-Y[i-1]));
  var len=cum[cum.length-1],N=Math.ceil(len/HS)+1,PX=new Float32Array(N),PY=new Float32Array(N),j=0;
  for(i=0;i<N;i++){var s=Math.min(i*HS,len);while(j<cum.length-2&&cum[j+1]<s)j++;var a=(s-cum[j])/Math.max(1e-9,cum[j+1]-cum[j]);PX[i]=X[j]+(X[j+1]-X[j])*a;PY[i]=Y[j]+(Y[j+1]-Y[j])*a;}
