      var pR=[W/2+(Fd[0]-cxR)*sR,H/2+(Fd[1]-cyR)*sR],e2=sm5(seg(t,T.back[0],T.back[1]));
      sc=Math.exp(L_(sM)+(L_(sR)-L_(sM))*e2);var px2=lerp(pD[0],pR[0],e2),py2=lerp(pD[1],pR[1],e2);c0=Fd[0]-(px2-W/2)/sc;c1=Fd[1]-(py2-H/2)/sc;
