  var w=warmCanvas();[S.skin,S.mud,S.mudS,S.lo,S.bead,S.lime[0],S.lime[1],S.lime[2],S.lime[3],C.wet,C.BGm,C.BGl].forEach(function(im){if(im&&ok(im))try{w.drawImage(im,0,0,8,8);}catch(e){}});
