  var X0=Math.max(0,(0-ox)/k),X1=Math.min(MW,(W-ox)/k),Y0=Math.max(0,(0-oy)/k),Y1=Math.min(MH,(H-oy)/k);if(X1<=X0||Y1<=Y0)return;
