var ASSETS=['cut/hi.webp','t_fresh.webp','t_skin.webp','t_mud.webp','t_mud_s.webp','t_mudlo.webp','t_bead.webp','t_lime0.webp','t_lime1.webp','t_lime2.webp','t_lime3.webp'];
