    // ===== DOM: the new wall once the mud covers the screen; the room's title and label as the band settles
    if(!warm){var inNew=t>=T.domNew||!ctx.from,ink=inNew?ctx.to.ink:ctx.from.ink,wl=inNew?ctx.to.wall:ctx.from.wall;
      if(S.inkNow!==ink){ctx.ui.ink(ink);S.inkNow=ink;}if(S.wallNow!==wl){ctx.ui.wall(wl);S.wallNow=wl;}
      var nw=G.narrow||W<=980;ctx.ui.title(ctx.to.idx,t>=(nw?T.titleN:T.title));var lab=t>=(nw?T.labelN:T.label);if(lab)placeLabel(ctx);ctx.ui.label(ctx.to.idx,lab);}
