// ---------------------------------------------------------------- the hung work, as core paintArt() paints the DOM canvas
function artCanvas(im,r,dpr){var w=Math.min(Math.round(r.w*dpr),2600),h=Math.round(w*(im.naturalHeight||1)/(im.naturalWidth||1));return cv(w,h);}
