  (function step(){if(!P.length){S.warm=null;c.width=c.height=1;return;}var p=P.shift();S.warm=true;try{q.setTransform(k,0,0,k,0,0);MOD.draw(p,w);}catch(e){}S.warm=null;setTimeout(step,24);})();
