var MID={H:1990,w0:18117,w1:22001,l0:17050,r1:23100};
var PIPA=18659,HXZ=21481;                       // the pipa player's belly (her hands / the pipa, main x ≈ 12730) · 韩熙载 (main x ≈ 14655)
var NA=PIPA-(HXZ-PIPA)/2,NB=HXZ+(HXZ-PIPA)/2,NL=NB-NA,NM=(NA+NB)/2;   // nodes 17248 · 20070 (touched) · 22892
var SY=938;                                     // the string's height (main y 640): between her hands and his face
var A2=540,A1=2400,PULL=46;                     // belly amplitudes (mid px): harmonic, fundamental; the pluck
var F2=0.9,F1=0.45;                             // slow-motion frequencies (Hz): well under 3 Hz
