  C.art=artCanvas(ctx.to.image,G.R,dpr,C.art);C.unf=artCanvas(S.unf,G.R,dpr,C.unf);C.ink=artCanvas(S.ink,G.R,dpr,C.ink);C.map=artCanvas(S.map,G.R,dpr,C.map);
  if(!C.mix)C.mix=cv(C.art.width,C.art.height);else if(C.mix.width!==C.art.width||C.mix.height!==C.art.height){C.mix.width=C.art.width;C.mix.height=C.art.height;}
