    var fs=sm(seg(t,T.fire)),front=lerp(-FW*2,1+FW*2,eio(seg(t,T.fire))*.15+seg(t,T.fire)*.85),
        glow=sm(seg(t,T.glowIn))*(1-sm(seg(t,T.glowOut)));
