  if(old){['art','fArt','rest','box'].forEach(function(n){var o=old[n];if(o&&o.c)o=o.c;if(o&&o.width){o.width=o.height=1;}});if(old.sheet)old.sheet.c.width=old.sheet.c.height=1;}
