    if(!S.warm){S.live=true;var inNew=t>=T.uiWall||!from,ink=inNew?ctx.to.ink:from.ink,wall=inNew?ctx.to.wall:from.wall;
      if(S.inkNow!==ink){ctx.ui.ink(ink);S.inkNow=ink;}if(S.wallNow!==wall){ctx.ui.wall(wall);S.wallNow=wall;}
      var nw=G.narrow||G.W<=980,tOn=nw?T.titleN:T.title,lOn=nw?T.labelN:T.label;
      ctx.ui.title(ctx.to.idx,t>=tOn);var lab=t>=lOn;if(lab)placeLabel(ctx);ctx.ui.label(ctx.to.idx,lab);}
    // ===== p 1: exactly the rest (wall + wash + the mount + the hung painting)
    if(t>=D-1e-6){g.fillStyle=ctx.to.wall;g.fillRect(0,0,W,H);wash(g,W,H,G.R,1,light);if(C.rest){g.save();g.setTransform(1,0,0,1,0,0);g.drawImage(C.rest.c,C.rest.X0,C.rest.Y0);g.restore();}blit(g,C.art,G.R,dpr);return;}
    // ===== ① ② the vase at rest, then the camera draws back and the wall turns pale
    var wu=from?sm(seg(t,T.wall)):1,fromLight=from&&from.ink==='dark';
    if(from&&wu<1){g.fillStyle=from.wall;g.fillRect(0,0,W,H);wash(g,W,H,from.rect,1-wu,fromLight);}
    if(wu>0){g.save();g.globalAlpha=wu;g.fillStyle=ctx.to.wall;g.fillRect(0,0,W,H);g.restore();wash(g,W,H,G.R,wu,light);}
    if(from&&t<T.vaseOut[1]){var k=t<T.recede[0]?1:lerp(1,RECEDE,eio(seg(t,T.recede)));drawVase(g,ctx,G,C,k,1-sm(seg(t,T.vaseOut)));}
