    if(p.x<lo-p.w*.3&&p.vx<0){p.x=lo-p.w*.3;p.vx=-p.vx*.3;}if(p.x+p.w>hi+p.w*.3&&p.vx>0){p.x=hi+p.w*.3-p.w;p.vx=-p.vx*.3;}
