    g.font='400 12px '+font;g.textBaseline='middle';g.textAlign='left';g.fillStyle=ink3;
    for(var m=0;m<=HMAX+1e-6;m+=.5){var yy=Math.round(sc(m))+.5;g.beginPath();g.moveTo(X0,yy);g.lineTo(X0+8,yy);g.stroke();if(m>0)g.fillText(nb(m.toFixed(1)+' '+T.unit),X0+12,yy);}
    // the hands' level: brightens as the rod comes down to it
    var c=S.cue,hy=sc(Math.max(0,S.hy));g.strokeStyle=c>.05?acc:ink3;g.lineWidth=1+2.5*c;g.beginPath();g.moveTo(X0+58,hy);g.lineTo(X0+104,hy);g.stroke();
    // the best height so far
