    // the rod and a hint of the silk below it
    var ry=sc(Math.max(0,S.y)),lean=clamp(S.wind/WIND,0,1)*.5;g.strokeStyle=ink;g.lineWidth=2.5;g.lineCap='round';g.beginPath();g.moveTo(X0+64,ry);g.lineTo(X0+98,ry);g.stroke();
    g.fillStyle=ink2;g.globalAlpha=.35;g.beginPath();g.moveTo(X0+66,ry+2);g.lineTo(X0+96,ry+2);g.lineTo(X0+96+lean*14,ry+16);g.lineTo(X0+66+lean*14,ry+16);g.closePath();g.fill();g.globalAlpha=1;
