    // pole
    var P=S.pole;if(P.on&&P.rel&&P.t>=.45){P.rel=false;P.on=false;if(pad.getAttribute('data-m')==='pole')pad.setAttribute('data-m','');}if(P.on){P.t+=dt;P.s=P.t<.18?P.t/.18:P.t<STROKE?1:Math.max(0,1-(P.t-STROKE)/FADE);if(P.t>STROKE&&P.t-dt<=STROKE)S.poleEndT=S.t;}else P.s=Math.max(0,P.s-dt*5);
