var TAU=Math.PI*2;

// ---------------------------------------------------------------- geometry (world = s_head pixels)
var HW=1262,HH=448,SSW=709,SSH=432;
var HX=40,HY=40;                                   // where the head strip lies on the table
var STAINS=[{u:508,y:147,w:46,h:120},{u:748,y:145,w:50,h:126},{u:998,y:148,w:48,h:122}];
