  // ---------------------------------------------------------------- camera
  var W=0,H=0,dpr=1,k=1,ox=0,oy=0;
  function size(){var w=cv.clientWidth;if(!w)return false;var h=Math.round(w*1000/1400);dpr=Math.min(window.devicePixelRatio||1,2);
    if(W!==w||H!==h||cv.width!==Math.round(w*dpr)){W=w;H=h;cv.width=Math.round(w*dpr);cv.height=Math.round(h*dpr);dirty=true;}return true;}
  function boxTarget(){var b=BASE.slice();
    var x1=S.joined?HX+HW+SSW+40:Math.max(b[2],S.ss.x+SSW/2+40);b[2]=Math.min(x1,HX+HW+SSW+80);b[0]=Math.min(0,S.ss.x-SSW/2-40);return b;}
  function cam(){var b=S.box,bw=b[2]-b[0],bh=b[3]-b[1];k=Math.min(W/bw,H/bh);ox=(W-bw*k)/2-b[0]*k;oy=(H-bh*k)/2-b[1]*k;}
