    for(var u=8;u<=s;u+=8){p=P(u);g.lineTo(p[0],p[1]);}p=P(s);g.lineTo(p[0],p[1]);g.lineTo(I.x+I.r*1.05,p[1]);g.stroke();
    // scorch marks on their layers
    var stackB=null;
    for(var i=0;i<STAINS.length;i++){var m=STAINS[i];if(m.u>s)continue;var b=a0-th(m.u),r=rc+kk*th(m.u)/TAU;
      g.strokeStyle='rgba(150,62,26,.95)';g.lineWidth=Math.max(3/k,kk*.7);g.beginPath();g.arc(I.x,I.y,r,Math.PI/2+b-.12,Math.PI/2+b+.12);g.stroke();
      if(stackB===null)stackB=b;}
    if(s>=HW-1){var be=a0-th(HW),re=rc+kk*th(HW)/TAU;g.strokeStyle='rgba(150,62,26,.95)';g.lineWidth=Math.max(3/k,kk*.7);g.beginPath();g.arc(I.x,I.y,re,Math.PI/2+be-.1,Math.PI/2+be+.02);g.stroke();}
