function sm(t){t=clamp(t,0,1);return t*t*(3-2*t);}
function nb(t){return String(t==null?'':t).replace(/([㐀-鿿）》”]) (?=[0-9A-Za-z])/g,'$1 ').replace(/([0-9A-Za-z.%°]) (?=[㐀-鿿（《“])/g,'$1 ');}
function ok(i){return !!(i&&i.complete&&i.naturalWidth>0);}
