    for(y=y0;y<=y1;y++){row=y*GW;for(x=x0;x<=x1;x++){i=row+x;dW[i]=0;dP[i]=0;}}
    for(y=y0;y<y1;y++){row=y*GW;for(x=x0;x<x1;x++){i=row+x;if(W[i]===0&&W[i+1]===0&&W[i+GW]===0)continue;flow(i,i+1);flow(i,i+GW);}}
    var nx0=GW,ny0=GH,nx1=-1,ny1=-1,ev=EV*dt,w,p,front,dep;
