    var wet=S.wet,mx=cw0/2,hy=ch*.46,tw=6+4*wet,tl=ch*.5*(.86+.14*wet),dark=1-Math.exp(-2.6*S.conc*(.25+.75*Math.min(1,wet*1.3))),gr=Math.round(236-dark*212);
