  var dirty=true,dead=false,raf=0,last=0;
  var tableSpot={x:(TABLE.x0+TABLE.x1)/2+4,y:TABLE.y-RR};  // centre of the rolled scroll on the table
  function apex(){return{x:tableSpot.x,y:tableSpot.y-RR-8};}

  // ---------- geometry of the pole
  function tip(){return{x:S.hx+LP*Math.sin(S.th),y:S.hy-LP*Math.cos(S.th)};}
  // where the visitor wants the hand and the lean so that the tip reaches the target
  function solve(Tt){var sg=Tt.x<150?-1:1,th=.14*sg,hy=Tt.y+LP*Math.cos(th);
    if(hy>HMAX){hy=HMAX;var c=clamp((HMAX-Tt.y)/LP,-1,1);th=sg*Math.acos(c);}
    if(hy<HMIN){hy=HMIN;th=0;}
    th=clamp(th,-1.45,1.45);var hx=Tt.x-LP*Math.sin(th),px=clamp(hx-18*sg,PXMIN,PXMAX);hx=px+18*sg;
    var s=clamp((Tt.x-hx)/LP,-.99,.99);th=clamp(Math.asin(s),-1.45,1.45);
    if(Tt.y>hy-LP*Math.cos(th)+2&&Math.abs(th)<1.45){var need=Math.acos(clamp((hy-Tt.y)/LP,-1,1));th=clamp(sg*Math.max(Math.abs(th),need),-1.45,1.45);}
    return{px:px,hy:hy,th:th,sg:sg};}

  // ---------- physics
  function loaded(){return S.mode==='carry';}
  var lastSolve=null;
  function stepPole(dt){
    var q=solve(S.T);lastSolve=q;
    // walk: limited speed and acceleration
    var want=clamp((q.px-S.px)*5,-150,150),dv=clamp(want-S.pvx,-700*dt,700*dt);S.pvx+=dv;S.px=clamp(S.px+S.pvx*dt,PXMIN,PXMAX);
    var hx=S.px+18*q.sg;
    var hvx=(hx-S.hx)/Math.max(dt,1e-4);S.hax=lerp(S.hax,(hvx-S.hvx)/Math.max(dt,1e-4),.35);S.hvx=hvx;S.hx=hx;
    // arm: raises / lowers the hand at a limited speed
    var hvy=clamp((q.hy-S.hy)*6,-240,240);S.hy=clamp(S.hy+hvy*dt,HMIN,HMAX);S.hvy=hvy;
    // pole: an inverted pendulum held by a springy wrist; the scroll at the tip adds weight (inertia, sag, lag)
    var ms=loaded()?2:0,I=1/3+ms,Mg=(.5+ms)*G/LP,Ma=(.5+ms)/LP,K=12,Cd=(reduce?2.4:1.25)+1.2*ms;   // loaded: ζ ≈ .34, a slow heavy sway that dies in a few seconds of holding still

    var n=Math.max(1,Math.ceil(dt/.004)),hh=dt/n;
    for(var i=0;i<n;i++){var sn=Math.sin(S.th),cs=Math.cos(S.th);
      var acc=(Mg*sn*.1-Ma*S.hax*cs+K*(q.th-S.th)-Cd*S.om)/I;S.om+=acc*hh;S.th+=S.om*hh;}
    if(S.th>1.5){S.th=1.5;S.om=Math.min(0,S.om);}if(S.th<-1.5){S.th=-1.5;S.om=Math.max(0,S.om);}
    var t=tip();S.ptx=S.tx;S.pty=S.ty;var ntvx=(t.x-S.tx)/Math.max(dt,1e-4),ntvy=(t.y-S.ty)/Math.max(dt,1e-4);
    S.tax=clamp(lerp(S.tax,(ntvx-S.tvx)/Math.max(dt,1e-4),.3),-1800,1800);S.tvx=ntvx;S.tvy=ntvy;S.tx=t.x;S.ty=t.y;}
  function stepDangle(dt,ax,len,zz){var w2=G/len,z=zz||(reduce?.2:.07),w=Math.sqrt(w2),n=Math.max(1,Math.ceil(dt/.004)),hh=dt/n;
    for(var i=0;i<n;i++){var a=-w2*Math.sin(S.ph)-(ax/len)*Math.cos(S.ph)-2*z*w*S.pv;S.pv+=a*hh;S.ph+=S.pv*hh;}
    S.ph=clamp(S.ph,-1.5,1.5);}
  function stepRibbons(dt,drive){var n=Math.max(1,Math.ceil(dt/.005)),hh=dt/n;S.flut=Math.max(0,S.flut-dt*.45);
    for(var j=0;j<2;j++)for(var i=0;i<n;i++){var noise=S.flut*(Math.sin(performance.now()/1000*(7.3+j*2.1)+j*1.7)*14+Math.sin(performance.now()/1000*13.1+j)*6);
      var a=-60*S.ry[j]-3.2*S.rv[j]-drive*1.4+noise;S.rv[j]+=a*hh;S.ry[j]+=S.rv[j]*hh;S.ry[j]=clamp(S.ry[j],-.9,.9);}}

  function say(m){S.msg=m;S.msgT=performance.now();}
  function drop(why){var t={x:S.tx+Math.sin(S.ph)*(CORD+RR),y:S.ty+Math.cos(S.ph)*(CORD+RR)};
    S.body={x:t.x,y:t.y,vx:S.tvx*.7+Math.cos(S.ph)*S.pv*(CORD+RR),vy:Math.max(-120,S.tvy*.5),a:0,va:(Math.random()-.5)*3,rest:0,on:null};
    S.mode='fall';S.lastDrop=why;S.ph=0;S.pv=0;say(T[why]||'');snd('slip',.6,function(){api.sfx.puff(.05,.35);});dirty=true;}
  function hook(k){S.mode='hooked';S.k=k;S.hookT=performance.now();var N=NAILS[k];
    // the cord moves from the fork to the nail; the dangling scroll keeps its swing
    snd('hook',.8,function(){api.sfx.tick(.07);api.sfx.thud(.05);});say(T.hooked);dirty=true;}
  function unrollStart(){if(S.mode!=='hooked')return;S.mode='unroll';S.h=0;S.hv=0;S.snapped=false;S.settle=0;S.flut=1;S.ctl=false;S.ptrDrag=false;
    var N=NAILS[S.k];S.T={x:N.x-120,y:N.y+60};say(T.unroll);
    snd('unroll',.8,function(){api.sfx.whoosh(.035,1.2);});dirty=true;}
  function retake(){if(S.mode!=='hung'&&S.mode!=='unroll')return;S.mode='rollup';S.found=false;resEl.textContent='';reBtn.hidden=true;dirty=true;}

  function stepScene(dt,now){
    stepPole(dt);
    var m=S.mode,A=apex(),N;
    if(m==='table'){
      var d=Math.hypot(S.tx-A.x,S.ty-A.y),sp=Math.hypot(S.tvx,S.tvy);
      if(d<14&&sp<260){S.mode='carry';S.ph=0;S.pv=0;S.liftY=S.ty;say(T.carry);snd('pick',.7,function(){api.sfx.tick(.05);});}}
    else if(m==='carry'){
      stepDangle(dt,S.tax,CORD+RR);
      // the dangling roll cannot sink into the table or the floor
      var ry=S.ty+Math.cos(S.ph)*(CORD+RR),rx=S.tx+Math.sin(S.ph)*(CORD+RR);
      var surf=(rx>TABLE.x0-SCR.w/2&&rx<TABLE.x1+SCR.w/2)?TABLE.y-RR:FY-RR;if(ry>surf){S.pv*=.8;}
      // prongs knock a nail on the way up; the cord drops onto a nail on the way down
      for(var i=0;i<NAILS.length;i++){N=NAILS[i];var dx=S.tx-N.x;
        if(S.pty>N.y+3&&S.ty<=N.y+3&&Math.abs(dx)>2.6&&Math.abs(dx)<7.5){S.om+=(dx>0?1:-1)*(.9+Math.min(1.2,-S.tvy/300))/LP*40;
          snd('tap',.7,function(){api.sfx.tick(.09);});}
        if(S.pty<N.y-1&&S.ty>=N.y-1){var ax=Math.abs(dx);
          if(ax<8){if(S.tvy>150||Math.abs(S.tvx)>110)drop('fast');else{hook(i);break;}}
          else if(ax<15)drop('edge');}}
      if(S.mode==='carry'){S.tiltT=(Math.abs(S.th)>1.2&&S.ty<260)?(S.tiltT||0)+dt:0;   // high up and leaning hard: the cord runs down the pole
        if(S.tiltT>.3)drop('tilt');else if(S.ty<S.liftY-50&&Math.abs(S.ph)>1.4)drop('swing');}}
    else if(m==='hooked'){
      stepDangle(dt,0,CORD+RR);N=NAILS[S.k];
      // letting go, or pulling the fork away, starts the unroll; so does keeping still for a while
      if(!S.ctl&&!S.keyHold&&performance.now()-S.hookT>350)unrollStart();
      else if(Math.hypot(S.tx-N.x,S.ty-N.y)>40)unrollStart();
      else if(performance.now()-S.hookT>6000)unrollStart();}
    else if(m==='unroll'){
      var len=CORD+Math.max(RR,S.h*.62+RR);
      if(!S.snapped){var Ac=reduce?420:640,D=2.4;S.hv+=(Ac-D*S.hv)*dt;S.h+=S.hv*dt;
        if(S.h>=LS){var v=S.hv;S.h=LS;S.snapped=true;S.hv=v*.12;S.pv+=((Math.random()<.5?-1:1)*(.05+Math.random()*.03))*(reduce?.4:1);S.flut=1;
          snd('knock',clamp(v/300,.35,1),function(){api.sfx.thud(.12);api.sfx.tick(.05);});}}
      else{S.hv+=(-2200*(S.h-LS)-26*S.hv)*dt;S.h+=S.hv*dt;S.h=Math.min(S.h,LS+3);}
      var before=S.pv;stepDangle(dt,0,len,S.snapped?(reduce?.4:.21):.12);   // silk against the wall: the swing dies in a few beats
     stepRibbons(dt,(S.pv-before)/Math.max(dt,1e-4)*.05+(S.snapped?0:S.hv*.002));
      if(S.snapped){var still=Math.abs(S.ph)<.004&&Math.abs(S.pv)<.012&&Math.abs(S.h-LS)<.3;S.settle=still?S.settle+dt:0;
        if(S.settle>.5){S.mode='hung';S.lastK=S.k;S.hungOnce=true;S.ph=0;S.pv=0;S.h=LS;S.hv=0;reBtn.hidden=false;showResult();say(T.settle);}}}
    else if(m==='hung'){stepRibbons(dt,0);}
    else if(m==='rollup'){S.h-=dt*(reduce?260:360);S.ph*=Math.exp(-dt*4);stepRibbons(dt,0);
      if(S.h<=0){S.h=0;S.mode='back';var N2=NAILS[S.k];S.back={t:0,from:{x:N2.x,y:N2.y+CORD+RR}};S.k=-1;}}
    else if(m==='fall'){var b=S.body;b.vy+=G*dt;b.x+=b.vx*dt;b.y+=b.vy*dt;b.a+=b.va*dt;
      var onT=b.x>TABLE.x0-10&&b.x<TABLE.x1+10&&b.y-b.vy*dt<=TABLE.y-RR+1,fl=onT?TABLE.y-RR:FY-RR;
      if(b.x<RR+60){b.x=RR+60;b.vx=Math.abs(b.vx)*.3;}if(b.x>SW-70){b.x=SW-70;b.vx=-Math.abs(b.vx)*.3;}
      if(b.y>fl){b.y=fl;var imp=b.vy;if(imp>140)snd('drop',clamp(imp/900,.3,1),function(){api.sfx.thud(clamp(imp/5000,.05,.2));});
        b.vy=-imp*.22;b.vx*=.6;b.va=b.vx/RR*.2;if(imp<120){b.vy=0;b.on=onT?'table':'floor';}}
      if(b.on){b.vx*=Math.exp(-5*dt);b.rest+=dt;if(b.rest>.7){S.mode='back';S.back={t:0,from:{x:b.x,y:b.y}};}}}
    else if(m==='back'){S.back.t+=dt/.9;if(S.back.t>=1){S.mode='table';S.back.t=1;}}
    // the visitor's gaze: up at the peak once the scroll hangs
    var wantLook=(S.mode==='hung'||S.mode==='unroll')&&S.k>=0?1:0;S.look=lerp(S.look,wantLook,1-Math.exp(-dt*2.5));
    if(S.mode==='unroll'||S.mode==='hung'){N=NAILS[S.k];S.T={x:N.x-150,y:N.y+70};}}

  function showFound(){foundEl.innerHTML='';var h=document.createElement('h4');h.textContent=T.sigTitle;foundEl.appendChild(h);
    [end(T.found),end(T.sigNote)].forEach(function(t){if(!t)return;var q=document.createElement('p');q.textContent=nb(t);foundEl.appendChild(q);});}
  function showResult(){var N=NAILS[S.k],bottom=N.y+CORD+SCR.tian+SCR.ge+PHc,m=((FY-bottom)/100).toFixed(1);resEl.textContent=nb(end(T.res[N.k])+fmt(T.height,{m:m}));}

  // ---------- drawing the scene
  function drawMount(x,top,h,ph){  // the unrolled part of the scroll, top rod at (x, top), length h; ph = sway about the nail (handled by caller)
    var w=SCR.w,x0=x-w/2,pinX=9.2*(w/121);
    g.save();g.beginPath();g.rect(x0-1,top,w+2,h);g.clip();
    g.fillStyle=C.tian;g.fillRect(x0,top,w,SCR.tian);
    var y1=top+SCR.tian;g.fillStyle=C.quan;g.fillRect(x0,y1,w,SCR.ge*2+PHc);
    var py=y1+SCR.ge;g.fillStyle=C.quan;g.fillRect(x0,py,w,PHc);
    if(mini){g.imageSmoothingQuality='high';g.drawImage(mini,x0+pinX,py,w-2*pinX,PHc);}else{g.fillStyle='#4a4133';g.fillRect(x0+pinX,py,w-2*pinX,PHc);}
    g.fillStyle=C.tian;g.fillRect(x0,py+PHc+SCR.ge,w,SCR.di);
    g.strokeStyle='rgba(40,30,20,.45)';g.lineWidth=.6;g.beginPath();g.moveTo(x0,y1);g.lineTo(x0+w,y1);g.moveTo(x0,py+PHc+SCR.ge);g.lineTo(x0+w,py+PHc+SCR.ge);g.stroke();
    g.restore();
    // 惊燕: two ribbons from the top rod down the 天头
    [.3,.7].forEach(function(f,j){var rx=x0+w*f,len=SCR.tian*.9,a=S.ry[j],vis=Math.min(h,len);if(vis<2)return;
      g.save();g.translate(rx,top);g.rotate(a);g.fillStyle=C.yan;g.strokeStyle='rgba(40,30,20,.5)';g.lineWidth=.5;
      g.beginPath();g.moveTo(-1.8,0);g.quadraticCurveTo(-1.8+a*6,vis*.5,-1.8+a*9,vis);g.lineTo(1.8+a*9,vis);g.quadraticCurveTo(1.8+a*6,vis*.5,1.8,0);g.closePath();g.fill();g.stroke();g.restore();});
    // top rod
    g.fillStyle=C.rod;g.fillRect(x0,top-1.4,w,2.2);}
  function drawRoll(x,y,spin){  // rolled scroll seen from the front: a horizontal cylinder with knobs
    var w=SCR.w,k=SCR.knob,gr=g.createLinearGradient(0,y-RR,0,y+RR);gr.addColorStop(0,C.quan);gr.addColorStop(.45,C.tian);gr.addColorStop(1,'#2a2219');
    g.fillStyle=gr;g.fillRect(x-w/2,y-RR,w,RR*2);
    // the turning edge of the silk (shows the spin)
    g.strokeStyle='rgba(30,22,14,.55)';g.lineWidth=.7;var s=((spin%(Math.PI*2))+Math.PI*2)%(Math.PI*2),yy=y-Math.cos(s)*RR*.8;
    g.beginPath();g.moveTo(x-w/2,yy);g.lineTo(x+w/2,yy);g.stroke();
    var kg=g.createLinearGradient(0,y-RR*.8,0,y+RR*.8);kg.addColorStop(0,C.knobHi);kg.addColorStop(.55,C.knob);kg.addColorStop(1,C.rod);
    g.fillStyle=kg;g.fillRect(x-w/2-k,y-RR*.75,k,RR*1.5);g.fillRect(x+w/2,y-RR*.75,k,RR*1.5);}
  function drawCordV(ax,ay,rx,ry,ang){ // cord from the apex (fork / nail) to both ends of the top rod
    var w=SCR.w*.42,c=Math.cos(ang),s=Math.sin(ang);g.strokeStyle='rgba(222,205,170,.85)';g.lineWidth=.9;g.beginPath();
    g.moveTo(rx-w*c,ry-w*s);g.lineTo(ax,ay);g.lineTo(rx+w*c,ry+w*s);g.stroke();}
  function drawRolledHanging(ax,ay,ang,spin){g.save();g.translate(ax,ay);g.rotate(-ang);var rx=0,ry=CORD+RR;
    drawCordV(0,0,rx,CORD-.6,0);drawRoll(rx,ry,spin||0);g.restore();}
  function drawPerson(){var px=S.px,sg=lastSolve?lastSolve.sg:1,crouch=clamp((S.hy-395)/50,0,1),top=FY-168+crouch*38,hx=S.hx,hy=S.hy;
    var ink=tok('--ink-3','#b3a893');g.save();g.fillStyle=ink;g.strokeStyle=ink;g.globalAlpha=.55;
    // robe
    g.beginPath();g.moveTo(px-13,top+30);g.lineTo(px+13,top+30);g.lineTo(px+24,FY);g.lineTo(px-24,FY);g.closePath();g.fill();
    // head (tilts back when looking up at the hung scroll)
    var lk=S.look*(S.k>=0?clamp((NAILS[S.k].y+60<FY-EYE?1:0)*(1-(NAILS[S.k].y-40)/200),.25,1):0);
    g.save();g.translate(px,top+14);g.rotate(-lk*.55*(sg));g.beginPath();g.ellipse(0,-2,9,11,0,0,Math.PI*2);g.fill();g.restore();
    // arms to the hand on the pole
    g.lineWidth=5;g.lineCap='round';g.beginPath();g.moveTo(px+6*sg,top+36);g.lineTo(hx,hy);g.stroke();
    g.beginPath();g.moveTo(px-4*sg,top+38);g.lineTo(lerp(px,hx,.6),lerp(top+60,hy+30,.6));g.lineTo(S.hx+Math.sin(S.th)*-26,S.hy+Math.cos(S.th)*26);g.stroke();
    g.restore();}
  function drawPole(){var t=tip(),bx=S.hx-Math.sin(S.th)*30,by=S.hy+Math.cos(S.th)*30;
    g.save();g.lineCap='round';g.strokeStyle='#8c7248';g.lineWidth=2.6;g.beginPath();g.moveTo(bx,by);g.lineTo(t.x,t.y);g.stroke();
    // bamboo nodes
    g.strokeStyle='rgba(50,36,20,.6)';g.lineWidth=3;for(var i=1;i<6;i++){var f=i/6,nx=lerp(bx,t.x,f),ny=lerp(by,t.y,f);g.beginPath();g.moveTo(nx-Math.cos(S.th)*1.2,ny-Math.sin(S.th)*1.2);g.lineTo(nx+Math.cos(S.th)*1.2,ny+Math.sin(S.th)*1.2);g.stroke();}
    // the iron fork (叉)
    g.translate(t.x,t.y);g.rotate(S.th);g.strokeStyle='#26221e';g.lineWidth=1.3;g.beginPath();g.moveTo(0,4);g.lineTo(0,0);g.moveTo(-4,-5);g.quadraticCurveTo(-4,0,0,0);g.quadraticCurveTo(4,0,4,-5);g.stroke();
    g.restore();}
  function drawNail(N,active){g.save();g.fillStyle='rgba(0,0,0,.35)';g.beginPath();g.ellipse(N.x+1.5,N.y+2.5,2.8,1.8,0,0,Math.PI*2);g.fill();
    var gr=g.createRadialGradient(N.x-1,N.y-1,.3,N.x,N.y,3.2);gr.addColorStop(0,'#c9a978');gr.addColorStop(1,'#5b4630');g.fillStyle=gr;g.beginPath();g.arc(N.x,N.y,2.6,0,Math.PI*2);g.fill();
    if(active){g.strokeStyle=tok('--ink-2','#d3c8b6');g.globalAlpha=.55;g.lineWidth=.8;g.beginPath();g.arc(N.x,N.y,9,0,Math.PI*2);g.stroke();}
    g.restore();}
  function drawTable(){var t=TABLE;g.save();g.fillStyle='#2b1f16';g.fillRect(t.x0,t.y,t.x1-t.x0,5);g.fillStyle='#3b2b1e';g.fillRect(t.x0,t.y,t.x1-t.x0,2);
    g.fillStyle='#241a12';g.fillRect(t.x0+8,t.y+5,5,FY-t.y-5);g.fillRect(t.x1-13,t.y+5,5,FY-t.y-5);g.fillRect(t.x0+8,t.y+20,t.x1-t.x0-16,2);
    g.fillStyle='rgba(0,0,0,.25)';g.beginPath();g.ellipse((t.x0+t.x1)/2,FY+2,(t.x1-t.x0)/2+6,4,0,0,Math.PI*2);g.fill();g.restore();}
  function draw(){var dpr=Math.min(devicePixelRatio||1,2),cw=cv.clientWidth;if(!cw)return;var w=Math.round(cw*dpr),h=Math.round(w*SH/SW);
    if(cv.width!==w||cv.height!==h){cv.width=w;cv.height=h;}
    var z=w/SW;g.setTransform(z,0,0,z,0,0);
    // wall with a soft light from the upper left, floor
    var wg=g.createLinearGradient(0,0,SW,SH);wg.addColorStop(0,C.wallHi);wg.addColorStop(.6,C.wall);wg.addColorStop(1,C.wall);g.fillStyle=wg;g.fillRect(0,0,SW,FY);
    g.fillStyle=C.floor;g.fillRect(0,FY,SW,SH-FY);g.fillStyle='rgba(0,0,0,.25)';g.fillRect(0,FY,SW,1.2);
    drawTable();
    var active=S.mode==='carry'?nearNail():-1;
    NAILS.forEach(function(N,i){drawNail(N,i===active);});
    var m=S.mode,N;
    // the scroll
    if(m==='table'){drawCordLoose();drawRoll(tableSpot.x,tableSpot.y,0);}
    else if(m==='carry'){drawRolledHanging(S.tx,S.ty,S.ph,0);}
    else if(m==='hooked'){N=NAILS[S.k];drawRolledHanging(N.x,N.y,S.ph,0);}
    else if(m==='unroll'||m==='hung'||m==='rollup'){N=NAILS[S.k];g.save();g.translate(N.x,N.y);g.rotate(-S.ph);
      // soft shadow on the wall
      g.fillStyle='rgba(0,0,0,.22)';g.fillRect(-SCR.w/2+3,CORD+2,SCR.w,Math.max(0,S.h));
      drawCordV(0,0,0,CORD-.6,0);drawMount(0,CORD,Math.max(0,S.h),S.ph);drawRoll(0,CORD+Math.max(0,S.h)+RR*.6,S.h/RR);g.restore();}
    else if(m==='fall'){var b=S.body;g.save();g.translate(b.x,b.y);g.rotate(b.a*.15);drawRoll(0,0,b.a);g.restore();}
    else if(m==='back'){var f=S.back.from,u=sm(S.back.t),x=lerp(f.x,tableSpot.x,u),y=lerp(f.y,tableSpot.y,u)-Math.sin(u*Math.PI)*40;drawRoll(x,y,u*6);}
    drawPerson();drawPole();drawLabels();
    // the target of the tip while steering (a small ring)
    if(S.ctl){g.save();g.strokeStyle=tok('--ink-2','#d3c8b6');g.globalAlpha=.4;g.lineWidth=.8;g.beginPath();g.arc(S.T.x,S.T.y,5,0,Math.PI*2);g.stroke();g.restore();}}
  function drawLabels(){var zc=cv.clientWidth/SW;if(!zc)return;var fs=12.5/zc,m=S.mode;
    g.save();g.font='400 '+fs.toFixed(2)+'px '+tok('--song','serif');g.fillStyle=tok('--ink-3','#b3a893');g.textBaseline='middle';
    if(m!=='unroll'&&m!=='hung'&&m!=='rollup'){g.textAlign='left';NAILS.forEach(function(N){g.fillText(T.lab[N.k],N.x+10,N.y);});
      g.textAlign='right';g.fillText(T.lab.hook,NAILS[0].x-10,NAILS[0].y);}
    if(m==='table'){var A=apex();g.textAlign='center';g.fillText(T.lab.cord,A.x,A.y-fs*1.1);
      var t=tip(),mx=lerp(S.hx,t.x,.55),my=lerp(S.hy,t.y,.55);g.textAlign='left';g.fillText(T.lab.pole,mx+10,my);}
    if((m==='hung'||m==='unroll')&&S.k>=0&&S.h>SCR.tian){var N=NAILS[S.k];g.textAlign='right';g.fillText(T.lab.yan,N.x-SCR.w/2-8,N.y+CORD+SCR.tian*.45);}
    g.restore();}
  function drawCordLoose(){var A=apex();g.strokeStyle='rgba(222,205,170,.85)';g.lineWidth=.9;g.beginPath();g.moveTo(tableSpot.x-SCR.w*.42,tableSpot.y-RR+.5);
    g.quadraticCurveTo(tableSpot.x-12,A.y-2,A.x,A.y);g.quadraticCurveTo(tableSpot.x+12,A.y-2,tableSpot.x+SCR.w*.42,tableSpot.y-RR+.5);g.stroke();}
  function nearNail(){var b=-1,bd=40;NAILS.forEach(function(N,i){var d=Math.hypot(S.tx-N.x,S.ty-N.y);if(d<bd){bd=d;b=i;}});return b;}

  // ---------- input: the scene (mouse / pen drag = absolute target), the pad (relative, all pointers), keys (window)
  function toScene(e){var r=cv.getBoundingClientRect();return{x:(e.clientX-r.left)*SW/r.width,y:(e.clientY-r.top)*SH/r.height};}
  function setT(p){S.T.x=clamp(p.x,8,SW-8);S.T.y=clamp(p.y,4,FY-6);}
  var drag=null;
  cv.addEventListener('pointerdown',function(e){if(dead||e.pointerType==='touch'||(e.pointerType==='mouse'&&e.button!==0))return;
    drag={id:e.pointerId};try{cv.setPointerCapture(e.pointerId);}catch(_){}cv.classList.add('drag');S.ctl=true;S.ptrDrag=true;setT(toScene(e));e.preventDefault();});
