  relBtn.addEventListener('click',function(){S.ctl=false;S.keyHold=false;keys={};if(S.mode==='hooked')unrollStart();});
  reBtn.addEventListener('click',retake);
  // keys: taken at the window while the exhibit is shown, whatever has focus (Safari gives none to a clicked canvas); a focused
