  var keys={};
  function mine(e){if(dead||!host.isConnected||!cv.getClientRects().length||e.altKey||e.ctrlKey||e.metaKey)return false;var tg=e.target;
    return !(tg&&(tg.tagName==='INPUT'||tg.tagName==='TEXTAREA'||tg.tagName==='SELECT'||tg.tagName==='BUTTON'||tg.isContentEditable));}
  var KM={w:'u',W:'u',ArrowUp:'u',s:'d',S:'d',ArrowDown:'d',a:'l',A:'l',d:'r',D:'r'};
