    for(k=S.splash.length-1;k>=0;k--){var s=S.splash[k];flow(s.x,s.y,outV,true);s.vx+=(outV[0]-s.vx)*Math.min(1,dt*1.2);s.vy+=(outV[1]-s.vy)*Math.min(1,dt*1.2);s.x+=s.vx*dt;s.y+=s.vy*dt;s.r+=dt*.9;s.age+=dt;if(s.age>s.life||s.y>WH+10)S.splash.splice(k,1);}
